import{_ as a,c as s,o as t,ah as i}from"./chunks/framework.BssxmkiH.js";const p=JSON.parse('{"title":"Best Practices","description":"","frontmatter":{},"headers":[],"relativePath":"best-practices.md","filePath":"best-practices.md"}'),r={name:"best-practices.md"};function o(n,e,c,l,d,h){return t(),s("div",null,e[0]||(e[0]=[i('<h1 id="best-practices" tabindex="-1">Best Practices <a class="header-anchor" href="#best-practices" aria-label="Permalink to “Best Practices”">​</a></h1><p>This section reveals practices you should follow to get the best performance out of Fast Sky 2. These tips are especially important if you are targeting low-end devices or want to achieve the best possible performance.</p><h2 id="minimize-your-lightmarch-steps" tabindex="-1">Minimize Your Lightmarch Steps <a class="header-anchor" href="#minimize-your-lightmarch-steps" aria-label="Permalink to “Minimize Your Lightmarch Steps”">​</a></h2><p>Try to use as few lightmarch steps as possible. If you&#39;re unsatisfied with the banding artifacts or visual quality, try to use <a href="./cloud-settings#main-settings">dithering</a> instead of increasing the lightmarch steps.</p><h2 id="disable-unused-features" tabindex="-1">Disable Unused Features <a class="header-anchor" href="#disable-unused-features" aria-label="Permalink to “Disable Unused Features”">​</a></h2><p>If you don&#39;t intend to use Godrays, Skymaps or the Moon, make sure to disable them in the Fast Sky component. This can help save some performance by avoiding unnecessary calculations and rendering.</p><h2 id="use-fast-mode" tabindex="-1">Use Fast Mode <a class="header-anchor" href="#use-fast-mode" aria-label="Permalink to “Use Fast Mode”">​</a></h2><p>The quality loss of using <a href="./cloud-settings#main-settings">Fast Mode</a> is quite minimal in most cases, but the performance gain can be significant especially on low-end devices. So if you are targeting a wide range of devices, it&#39;s recommended to use <a href="./cloud-settings#main-settings">Fast Mode</a>.</p><h2 id="use-fewer-cloud-layers" tabindex="-1">Use Fewer Cloud Layers <a class="header-anchor" href="#use-fewer-cloud-layers" aria-label="Permalink to “Use Fewer Cloud Layers”">​</a></h2><p>More <a href="./cloud-settings#cloud-layer">cloud layers</a> means more computation. Try to use fewer when possible.</p><h2 id="debugging-tips" tabindex="-1">Debugging Tips <a class="header-anchor" href="#debugging-tips" aria-label="Permalink to “Debugging Tips”">​</a></h2><ol><li><strong>Isolate Variables</strong>: Disable/adjust features one at a time to see their impact on performance. You can better observe performance changes by rendering your game in high-resolution and comparing the FPS changes.</li><li><strong>Test on Target Hardware</strong>: Always test on the lowest-end device you plan to support.</li></ol>',12)]))}const m=a(r,[["render",o]]);export{p as __pageData,m as default};
